const SCALE = 104174.1446;
const TX = -164200.0000;
const TY = 44793.9090;

/** Longitude/latitude to map coordinates, matching the paths above. */
export function projectDhaka(lng: number, lat: number) {
  const x = TX + SCALE * ((lng * Math.PI) / 180);
  const y = TY - SCALE * Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));
  return { x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 };
}
